paths=[p.parent/'revision-corpulence/repos-trois-quart-01.png',p/'essai-manuel-jambe-1.png',p/'essai-manuel-jambe-2.png',p.parent/'refs-spritecollab/Walk-Anim.png']
src=['data:image/png;base64,'+base64.b64encode(q.read_bytes()).decode() for q in paths]
s='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Étude de marche en lévitation</title><style>*{box-sizing:border-box}body{background:#14231d;color:#ecf3e9;font:16px system-ui;margin:0}main{max-width:1100px;margin:auto;padding:25px}h1{font-size:26px}p{line-height:1.5}.warning{background:#4c3b27;border-left:4px solid #ffc375;padding:14px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{padding:16px;background:#263b30;border-radius:12px}.stage{height:370px;background:#ccdcc1;display:grid;place-items:center;overflow:hidden}canvas{image-rendering:pixelated;width:100%;height:100%}button{padding:10px;background:#d8e9d1;border:0;border-radius:6px;font-weight:bold}.small{font-size:14px;color:#c9d8c7}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style><main><h1>Marche en lévitation · première étude</h1><p class="warning"><b>Essai non final :</b> les jambes ont été raccourcies sur des copies pour tester l’alternance. Le mouvement reste raide, les raccords sont à corriger et les bras ne sont pas encore animés. Ce n’est pas une marche PMDO terminée.</p><p>La tête, le visage, le costume et les bras restent identiques à la vue avant-droite validée : aucune modification au-dessus de la zone des jambes. Original conservé.</p><button id="p">Pause</button> <span id="n"></span><div class="grid"><div class="card"><h2>Tsareena de base · référence</h2><div class="stage"><canvas id="r" width="500" height="370"></canvas></div></div><div class="card"><h2>Méga · copies retouchées</h2><div class="stage"><canvas id="m" width="500" height="370"></canvas></div></div></div><p class="small">Séquence de travail : original / jambe 1 relevée / original / jambe 2 relevée. Durées de marche de la source : 8, 10, 8, 10 ticks à 60 Hz. L’oscillation verticale simule la lévitation : elle n’est pas issue de SpriteCollab. Référence : SpriteCollab / baronessfaron.</p></main><script>const urls=__DATA__;const imgs=urls.map(src=>{let i=new Image;i.src=src;return i});let elapsed=0,start=performance.now(),paused=false;const ticks=[8,10,8,10],frames=[0,1,0,2],lift=[4,7,4,7];document.querySelector('#p').onclick=()=>{paused=!paused;document.querySelector('#p').textContent=paused?'Reprendre':'Pause';if(!paused)start=performance.now()-elapsed};function loop(t){if(!paused)elapsed=t-start;let k=elapsed*60/1000%36,f=0;for(;f<3&&k>=ticks[f];f++)k-=ticks[f];document.querySelector('#n').textContent=' Image '+(f+1)+' / 4';let r=document.querySelector('#r').getContext('2d'),m=document.querySelector('#m').getContext('2d');r.imageSmoothingEnabled=false;m.imageSmoothingEnabled=false;r.clearRect(0,0,500,370);m.clearRect(0,0,500,370);if(imgs[3].complete)r.drawImage(imgs[3],f*32,56,32,56,138,0,224,392);if(imgs[frames[f]].complete){let im=imgs[frames[f]];m.drawImage(im,103,-lift[f]+6,294,370)}requestAnimationFrame(loop)}requestAnimationFrame(loop);</script></html>'''
(p/'Marche-levitation-premiere-etude.html').write_text(s.replace('__DATA__',json.dumps(src)),encoding='utf-8')
